steps.script:
function transform(ctx) {
  var rawIsp = (ctx.isp || "").replace(/^\s+|\s+$/g, "");

  // 运营商关键字 -> 账号后缀（锐捷 ePortal 以 @cmcc / @unicom / @telecom 区分线路）
  var suffixMap = {
    "校园网": "", "校内": "", "校园": "", "教育网": "", "campus": "",
    "中国移动": "@cmcc", "移动": "@cmcc", "cmcc": "@cmcc", "mobile": "@cmcc",
    "中国联通": "@unicom", "联通": "@unicom", "unicom": "@unicom", "cu": "@unicom",
    "中国电信": "@telecom", "电信": "@telecom", "telecom": "@telecom", "ct": "@telecom"
  };

  var suffix = "";
  if (rawIsp.charAt(0) === "@") {
    suffix = rawIsp;
  } else if (suffixMap[rawIsp] !== undefined) {
    suffix = suffixMap[rawIsp];
  } else if (suffixMap[rawIsp.toLowerCase()] !== undefined) {
    suffix = suffixMap[rawIsp.toLowerCase()];
  }

  // ",0," 域前缀固定写在请求地址里，这里只负责学号与运营商后缀
  var u = String(ctx.username || "").replace(/^\s+|\s+$/g, "");
  if (/^,0,/.test(u)) {
    u = u.slice(3);
  }
  if (u.indexOf("@") === -1) {
    u = u + suffix;
  }

  return {
    username: u,
    password: url_encode(ctx.password)
  };
}
